import fs from "node:fs";

const files = process.argv.slice(2);
for (const listFile of files) {
    const text = fs.readFileSync(listFile, "utf8");
    const lines = text.split(/\r?\n/);
    const byFile = new Map();
    for (const line of lines) {
        const m = line.match(/^\s{2}(\S+):(\d+)\s+<[\w-]+>\s/);
        if (!m) continue;
        const [, relPath, lineNoStr] = m;
        const lineNo = Number(lineNoStr);
        if (!byFile.has(relPath)) byFile.set(relPath, new Set());
        byFile.get(relPath).add(lineNo);
    }
    for (const [relPath, lineNos] of byFile) {
        const abs = relPath;
        const content = fs.readFileSync(abs, "utf8");
        const fileLines = content.split(/\r?\n/);
        for (const lineNo of lineNos) {
            const idx = lineNo - 1;
            const before = fileLines[idx];
            const count = (before.match(/\bdisableTooltip\b/g) || []).length;
            if (count !== 1) {
                console.error(`UNEXPECTED count=${count} at ${relPath}:${lineNo}`);
                continue;
            }
            fileLines[idx] = before.replace(/\bdisableTooltip\b/, "hideHint");
        }
        fs.writeFileSync(abs, fileLines.join(content.includes("\r\n") ? "\r\n" : "\n"));
    }
    console.log(`${listFile}: processed ${byFile.size} files`);
}

